package com.paybridge.spring;
import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties("paybridge") public class PayBridgeProperties { private Stripe stripe=new Stripe(); private Bkash bkash=new Bkash(); private Sslcommerz sslcommerz=new Sslcommerz(); public Stripe getStripe(){return stripe;} public void setStripe(Stripe v){stripe=v;} public Bkash getBkash(){return bkash;} public void setBkash(Bkash v){bkash=v;} public Sslcommerz getSslcommerz(){return sslcommerz;} public void setSslcommerz(Sslcommerz v){sslcommerz=v;} public static class Stripe { private boolean enabled; private String secretKey; public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public String getSecretKey(){return secretKey;} public void setSecretKey(String v){secretKey=v;} } public static class Bkash { private boolean enabled;private String appKey,appSecret,username,password,baseUri,callbackUri; public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public String getAppKey(){return appKey;}public void setAppKey(String v){appKey=v;}public String getAppSecret(){return appSecret;}public void setAppSecret(String v){appSecret=v;}public String getUsername(){return username;}public void setUsername(String v){username=v;}public String getPassword(){return password;}public void setPassword(String v){password=v;}public String getBaseUri(){return baseUri;}public void setBaseUri(String v){baseUri=v;}public String getCallbackUri(){return callbackUri;}public void setCallbackUri(String v){callbackUri=v;} } public static class Sslcommerz { private boolean enabled; private String storeId,storePassword,baseUri,successUri,failureUri,cancelUri,ipnUri; public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public String getStoreId(){return storeId;}public void setStoreId(String v){storeId=v;}public String getStorePassword(){return storePassword;}public void setStorePassword(String v){storePassword=v;}public String getBaseUri(){return baseUri;}public void setBaseUri(String v){baseUri=v;}public String getSuccessUri(){return successUri;}public void setSuccessUri(String v){successUri=v;}public String getFailureUri(){return failureUri;}public void setFailureUri(String v){failureUri=v;}public String getCancelUri(){return cancelUri;}public void setCancelUri(String v){cancelUri=v;}public String getIpnUri(){return ipnUri;}public void setIpnUri(String v){ipnUri=v;} } }
